      vector-effect: non-scaling-stroke;
      transition: stroke 150ms ease, stroke-width 150ms ease, filter 150ms ease; }
svg [data-legend-count-badge] { pointer-events: none; }
svg [data-legend-count-badge] rect { fill: var(--mask);
